PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,phone TEXT,password_hash TEXT,account_status TEXT NOT NULL DEFAULT 'pending' CHECK(account_status IN('pending','active','suspended','closed')),email_verified_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('customer','host','admin','moderator')),granted_at TEXT NOT NULL,granted_by TEXT,PRIMARY KEY(user_id,role));
CREATE TABLE IF NOT EXISTS host_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,business_name TEXT,contact_phone TEXT,verification_status TEXT NOT NULL DEFAULT 'not_submitted' CHECK(verification_status IN('not_submitted','pending','verified','rejected','suspended')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS host_enquiries(id TEXT PRIMARY KEY,name TEXT NOT NULL,contact TEXT NOT NULL,area TEXT NOT NULL,space_type TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contact_messages(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY,host_user_id TEXT REFERENCES users(id),host_email TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',town TEXT NOT NULL,neighbourhood TEXT NOT NULL DEFAULT '',space_type TEXT NOT NULL,size_label TEXT NOT NULL DEFAULT 'small',price_amount REAL NOT NULL,price_period TEXT NOT NULL DEFAULT 'month',currency TEXT NOT NULL DEFAULT 'KES',access_summary TEXT NOT NULL DEFAULT '',security_summary TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending_review','published','rejected','suspended')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_spaces_public ON spaces(status,town,space_type,created_at);
CREATE INDEX IF NOT EXISTS idx_spaces_host ON spaces(host_user_id,status);
CREATE TABLE IF NOT EXISTS space_photos(id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE,r2_key TEXT NOT NULL,is_cover INTEGER NOT NULL DEFAULT 0,alt_text TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS space_availability(id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available' CHECK(status IN('available','blocked','reserved')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES spaces(id),renter_user_id TEXT REFERENCES users(id),renter_email TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,total_amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'KES',status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN('requested','accepted','declined','awaiting_payment','confirmed','active','completed','cancelled','disputed')),payment_reference TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_email TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at);
